<template><div><div class="page-head"><div><h1>Sales Report</h1><p>Revenue mix, transaction volume, discounts and credit exposure.</p></div><div class="action-row"><input v-model="from" class="input" type="date"><input v-model="to" class="input" type="date"><button class="btn btn-primary" @click="load">Refresh</button></div></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-5"><div v-for="m in metrics" :key="m.label" class="card metric"><div class="metric-label">{{m.label}}</div><div class="metric-value mt-2">{{m.money?money(m.value):format(m.value)}}</div></div></div><div class="card mt-4 p-5"><h2 class="text-sm font-extrabold">Revenue by day</h2><div class="mt-6 flex h-56 items-end gap-2"><div v-for="d in data.daily||[]" :key="d.day" class="flex-1"><div class="mx-auto max-w-12 rounded-t-lg bg-gradient-to-t from-slate-900 to-indigo-400" :style="{height:`${bar(d.total)}%`}"></div><div class="mt-2 text-center text-[9px] text-slate-400">{{day(d.day)}}</div></div></div></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api} from '../../services/api';import {formatDate as formatDisplayDate} from '../../utils/date';const d=new Date(),from=ref(new Date(d.getFullYear(),d.getMonth(),1).toISOString().slice(0,10)),to=ref(d.toISOString().slice(0,10)),data=ref<any>({daily:[]});function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function format(v:any){return new Intl.NumberFormat('en-TZ').format(Number(v||0))}const metrics=computed(()=>[{label:'Total sales',value:data.value.total,money:true},{label:'Transactions',value:data.value.count},{label:'Paid sales',value:data.value.cash_or_paid,money:true},{label:'Credit sales',value:data.value.credit,money:true},{label:'Discounts',value:data.value.discounts,money:true}]);const max=computed(()=>Math.max(1,...(data.value.daily||[]).map((x:any)=>Number(x.total||0))));function bar(v:any){return Math.max(8,Number(v||0)/max.value*100)}function day(v:any){return new Intl.DateTimeFormat('en-TZ',{timeZone:'Africa/Dar_es_Salaam',weekday:'short'}).format(new Date(v)).slice(0,3)}async function load(){data.value=(await api.get('/reports/sales',{params:{from:from.value,to:to.value}})).data}onMounted(load)</script>
